const JOIN_ECHO_RE = /^\[(2[0-3]|[01]\d):([0-5]\d):([0-5]\d)\] \[Server thread\/INFO\]: (\S+) joined the game$/

/**
 * The champion eighth breath census - the champion cadence list's own
 * EIGHTH GAP the adjacent pair at index seven prices (the .365 champion
 * first breath the opening prices, the .367 champion second breath
 * the runner-up priced, the .369 champion third breath the third
 * priced, the .371 champion fourth breath the fourth priced, the
 * .373 champion fifth breath the fifth priced, the .375 champion
 * sixth breath the sixth priced, the .379 champion seventh breath
 * the seventh priced, the eighth this seat keeps).
 *
 * @param {string[]} lines - the server console face's own lines
 * @returns {{rejoinChampEighthBreath: number}|null} the eighth gap or null (non-array)
 */
export function rejoinChampEighthBreathCensus (lines) {
  if (!Array.isArray(lines)) return null
  const tally = new Map()
  const evts = [] // every echo the file order keeps ({name, second, tally})
  for (const l of lines) {
    if (typeof l !== 'string') continue
    const m = JOIN_ECHO_RE.exec(l)
    if (!m) continue
    const n = (tally.get(m[4]) || 0) + 1
    tally.set(m[4], n)
    evts.push({ name: m[4], s: Number(m[1]) * 3600 + Number(m[2]) * 60 + Number(m[3]), n })
  }
  let peak = 0
  for (const n of tally.values()) if (n > 1) peak = Math.max(peak, n - 1) // the tallest column
  const champs = new Set()
  for (const [name, n] of tally) if (n > 1 && n - 1 === peak) champs.add(name) // the TIE co-reigns
  const cevts = evts.filter(e => e.n > 1 && champs.has(e.name)) // the champion events the FILE ORDER keeps
  const gaps = []
  for (let i = 1; i < cevts.length; i++) {
    const cur = cevts[i - 1].s
    const nxt = cevts[i].s
    gaps.push(nxt >= cur ? nxt - cur : nxt + 86400 - cur) // the day-cyclic wrap
  }
  return { rejoinChampEighthBreath: gaps.length > 7 ? gaps[7] : 0 } // the EIGHTH the champion cadence keeps (the constructive zero the fewer-than-eight-gaps convention keeps)
}

